package com.tyes.civilisation.construction;
import com.tyes.civilisation.CivilisationMod;import com.tyes.civilisation.citizen.*;import com.tyes.civilisation.construction.blueprint.*;import com.tyes.civilisation.construction.building.BuildingRecord;import com.tyes.civilisation.construction.material.*;import com.tyes.civilisation.construction.project.*;import com.tyes.civilisation.construction.style.*;import com.tyes.civilisation.economy.inventory.*;import com.tyes.civilisation.economy.item.ItemKey;import com.tyes.civilisation.economy.shortage.ShortageSeverity;import com.tyes.civilisation.economy.shortage.ShortageType;import com.tyes.civilisation.persistence.ConstructionSavedData;import com.tyes.civilisation.server.CivilisationServices;import com.tyes.civilisation.settlement.SettlementState;import com.tyes.civilisation.settlement.WorkRole;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.tags.BiomeTags;import net.minecraft.world.Container;import net.minecraft.world.item.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.ChestBlockEntity;import net.minecraft.world.level.levelgen.Heightmap;
public final class ConstructionService {
 private final MinecraftServer server;private final ConstructionSavedData data;
 public ConstructionService(MinecraftServer server){this.server=server;this.data=ConstructionSavedData.get(server);}public ConstructionSavedData data(){return data;}
 public void tick(){long now=server.overworld().getGameTime();if(now%200!=0)return;var economy=CivilisationServices.economy(server);for(var p:data.projects()){if(p.state()==ConstructionProjectState.COMPLETE||p.state()==ConstructionProjectState.CANCELLED||p.state()==ConstructionProjectState.PAUSED)continue;reconcileClaims(p);ServerLevel level=server.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,p.stockpile().dimension()));Container stock=level==null?null:stockpile(p,level).orElse(null);if(stock==null){p.setState(ConstructionProjectState.BLOCKED,level==null||!level.isLoaded(p.stockpile().pos())?ConstructionBlocker.CHUNK_UNLOADED:ConstructionBlocker.STOCKPILE_DESTROYED);data.setDirty();continue;}revalidateCompleted(p,level);if(p.completedPlacements()==p.totalPlacements()){attemptComplete(p);data.setDirty();continue;}if(p.needsAccess())ensureTemporaryAccess(p,level);Map<ResourceLocation,Integer> missing=requirementsRemaining(p);boolean any=false;for(var e:missing.entrySet()){ItemKey key=ItemKey.parse(e.getKey().toString());int have=count(stock,key);int held=p.held(e.getKey());var estate=economy.data().forSettlement(p.settlementId());int incoming=estate.deliveryRequests().stream().filter(d->d.destination().equals(p.stockpileEndpoint())&&d.item().itemId().equals(key.itemId())&&d.state()!=com.tyes.civilisation.economy.logistics.DeliveryState.COMPLETE&&d.state()!=com.tyes.civilisation.economy.logistics.DeliveryState.CANCELLED).mapToInt(com.tyes.civilisation.economy.logistics.DeliveryRequest::quantity).sum();int producing=estate.productionRequests().stream().filter(r->r.output().itemId().equals(key.itemId())&&r.reason()==com.tyes.civilisation.economy.production.ProductionReason.CONSTRUCTION&&r.state()!=com.tyes.civilisation.economy.production.ProductionState.COMPLETE&&r.state()!=com.tyes.civilisation.economy.production.ProductionState.CANCELLED&&r.state()!=com.tyes.civilisation.economy.production.ProductionState.BLOCKED).mapToInt(com.tyes.civilisation.economy.production.ProductionRequest::remainingQuantity).sum();economy.promoteConstructionSupply(p.settlementId(),p.projectId(),key,p.priority());int deficit=e.getValue()-have-held-incoming-producing;if(deficit>0)economy.requestConstructionSupply(p.settlementId(),p.projectId(),p.stockpileEndpoint(),key,deficit,p.priority());if(have+held>0)any=true;}if(any&&p.state()!=ConstructionProjectState.BUILDING)p.setState(ConstructionProjectState.READY,ConstructionBlocker.NONE);else if(!any&&p.state()!=ConstructionProjectState.BUILDING)p.setState(ConstructionProjectState.WAITING_FOR_DELIVERY,ConstructionBlocker.MISSING_MATERIAL);data.setDirty();}}
 private void reconcileClaims(ConstructionProject p){var citizens=com.tyes.civilisation.persistence.CitizenSavedData.get(server).registry();for(var claim:p.claims().entrySet()){CitizenRecord citizen=citizens.find(claim.getValue()).orElse(null);boolean valid=citizen!=null&&citizen.presence()!=RuntimePresence.DECEASED&&(matchesBuilderClaim(citizen.brainPersistence().activeTaskType(),citizen.brainPersistence().activeTaskData(),p.projectId(),claim.getKey())||matchesBuilderClaim(citizen.brainPersistence().suspendedTaskType(),citizen.brainPersistence().suspendedTaskData(),p.projectId(),claim.getKey()));if(!valid)p.release(claim.getKey(),claim.getValue());}}
 private boolean matchesBuilderClaim(String type,net.minecraft.nbt.CompoundTag task,UUID project,int index){return com.tyes.civilisation.brain.task.BuilderTask.TYPE.equals(type)&&task.hasUUID("project")&&project.equals(task.getUUID("project"))&&task.getInt("index")==index;}
 public ConstructionProject createStarterHouse(SettlementState settlement) {return createStarterHouse(settlement,ConstructionPriority.NORMAL,"developer/admin construction",server.overworld().getGameTime());}
 public ConstructionProject createStarterHouse(SettlementState settlement,ConstructionPriority priority,String priorityReason,long now) {
  ServerLevel level=server.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,settlement.centre().dimension()));if(level==null)throw new IllegalStateException("Missing dimension");
  Site site=selectStarterHouseSite(settlement,level);BlockPos anchor=site.anchor();ArchitectureStyleProfile style=site.style();MaterialPalette palette=palette(style,settlement,level);ResolvedBlueprint blueprint=starter(style,palette);
  BlockPos stock=site.stockpile();level.setBlockAndUpdate(stock,Blocks.CHEST.defaultBlockState());
  var economy=CivilisationServices.economy(server);var endpoint=economy.registerEndpoint(settlement.settlementId(),AssignedLocation.at(level,stock),InventoryEndpointType.CONSTRUCTION_STOCKPILE,InventoryOwnership.WORKPLACE);
  ConstructionProject p=new ConstructionProject(UUID.randomUUID(),data.nextId(),settlement.settlementId(),AssignedLocation.at(level,anchor),AssignedLocation.at(level,stock),endpoint.id(),blueprint,palette);data.add(p);
  p.updatePriority(priority,priorityReason,now);requirements(blueprint).forEach((id,n)->economy.requestConstructionSupply(settlement.settlementId(),p.projectId(),endpoint.id(),ItemKey.parse(id.toString()),n,priority));p.setState(ConstructionProjectState.WAITING_FOR_DELIVERY,ConstructionBlocker.NONE);data.setDirty();return p;
 }
 private Site selectStarterHouseSite(SettlementState settlement,ServerLevel level){
  int[][] offsets={{0,14},{10,14},{-10,14},{14,0},{-14,0},{10,-16},{-10,-16},{20,10},{-20,10},{20,-10},{-20,-10},{0,24},{24,0},{-24,0},{0,-24}};
  for(int[] offset:offsets){BlockPos seed=settlement.centre().pos().offset(offset[0],0,offset[1]);int y=level.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,seed.getX(),seed.getZ());BlockPos anchor=new BlockPos(seed.getX(),y,seed.getZ());ArchitectureStyleProfile style=style(level,anchor);ResolvedBlueprint blueprint=starter(style,palette(style,settlement,level));BlockPos stock=anchor.offset(-2,0,4);try{validateSite(level,anchor,blueprint);if(!level.isLoaded(stock)||!level.getBlockState(stock).canBeReplaced())continue;if(data.projects().stream().anyMatch(p->p.state()!=ConstructionProjectState.CANCELLED&&(p.plansWorldPosition(stock)||blueprint.blocks().stream().map(b->b.relativePos().resolve(anchor)).anyMatch(p::plansWorldPosition))))continue;return new Site(anchor,stock,style);}catch(IllegalStateException ignored){}}
  throw new IllegalStateException("No valid starter-house site within the bounded settlement expansion area");
 }
 public Optional<Claim> claim(CitizenRecord citizen){UUID sid=citizen.settlementId().orElse(null);if(sid==null)return Optional.empty();reconcileCargoReferences(citizen);for(var p:data.projects().stream().filter(project->project.settlementId().equals(sid)&&isActive(project)).sorted(Comparator.comparingInt(project->project.priority().ordinal())).toList()){Set<UUID> assigned=assignedBuilderIds(p);boolean returningCargo=p.cargoOwners().contains(citizen.citizenId());if(assigned.size()>=desiredBuilders(sid)&&!assigned.contains(citizen.citizenId())&&!returningCargo)continue;var i=p.claim(citizen.citizenId(),p.heldBy(citizen.citizenId()).keySet());if(i.isPresent()){data.setDirty();return Optional.of(new Claim(p.projectId(),i.getAsInt(),p.priority()));}}return Optional.empty();}
 public int desiredBuilders(UUID settlementId){List<ConstructionProject> active=data.projects().stream().filter(p->p.settlementId().equals(settlementId)&&isActive(p)).toList();if(active.isEmpty())return 0;ConstructionProject lead=active.stream().min(Comparator.comparingInt(p->p.priority().ordinal())).orElseThrow();int population=(int)com.tyes.civilisation.persistence.CitizenSavedData.get(server).registry().all().stream().filter(c->c.settlementId().filter(settlementId::equals).isPresent()&&c.presence()!=RuntimePresence.DECEASED&&c.development().lifeStage().mayPerformFullWork()).count();int demand=switch(lead.priority()){case CRITICAL->3;case HIGH->2;case NORMAL,LOW->1;};int remaining=lead.totalPlacements()-lead.completedPlacements();if(remaining>128)demand++;int populationLimit=Math.max(1,(population+3)/4);ShortageSeverity food=CivilisationServices.economy(server).data().forSettlement(settlementId).shortages().getOrDefault(ShortageType.FOOD,ShortageSeverity.NONE);if(food==ShortageSeverity.SERIOUS||food==ShortageSeverity.CRITICAL)demand=1;return Math.min(populationLimit,demand);}
 public int assignedBuilders(UUID settlementId){Set<UUID> ids=new HashSet<>();data.projects().stream().filter(p->p.settlementId().equals(settlementId)&&isActive(p)).forEach(p->ids.addAll(assignedBuilderIds(p)));return ids.size();}
 public int availableBuilders(UUID settlementId){return(int)com.tyes.civilisation.persistence.CitizenSavedData.get(server).registry().all().stream().filter(c->c.settlementId().filter(settlementId::equals).isPresent()&&c.presence()!=RuntimePresence.DECEASED&&c.development().lifeStage().mayPerformFullWork()).filter(c->c.workRole()==WorkRole.BUILDER||c.development().career()==WorkRole.BUILDER||c.workRole()==WorkRole.GENERAL_LABOURER||c.workRole()==WorkRole.HAULER||c.workRole()==WorkRole.CRAFTER).filter(c->CivilisationServices.activeCitizens(server).bodyFor(c.citizenId()).isPresent()).count();}
 public Optional<ConstructionPriority> timberPriority(UUID settlementId){
  var economy=CivilisationServices.economy(server);
  var estate=economy.data().forSettlement(settlementId);
  boolean productionNeedsLogs=false;
  for(var request:estate.productionRequests()){
   if(request.state()==com.tyes.civilisation.economy.production.ProductionState.COMPLETE||request.state()==com.tyes.civilisation.economy.production.ProductionState.CANCELLED)continue;
   if(isTimberPath(request.output().itemId().getPath())&&request.blocker()==com.tyes.civilisation.economy.production.ProductionBlocker.MISSING_RECIPE){productionNeedsLogs=true;break;}
   for(var need:request.needs().entrySet())if(isTimberPath(need.getKey().itemId().getPath())&&economy.index().observed(settlementId,need.getKey())<need.getValue()){productionNeedsLogs=true;break;}
   if(productionNeedsLogs)break;
  }
  ConstructionPriority result=null;
  for(ConstructionProject project:data.projects()){
   if(!project.settlementId().equals(settlementId)||!isActive(project))continue;
   boolean timberShort=productionNeedsLogs;
   if(!timberShort)for(var entry:accounting(project).entrySet()){
    String path=entry.getKey().getPath();
    if(!isTimberPath(path))continue;
    ItemKey key=ItemKey.parse(entry.getKey().toString());
    if(entry.getValue().missing()>economy.index().observed(settlementId,key)){timberShort=true;break;}
   }
   if(timberShort&&(result==null||project.priority().outranks(result)))result=project.priority();
  }
  return Optional.ofNullable(result);
 }
 private boolean isTimberPath(String path){return path.endsWith("_log")||path.endsWith("_stem");}
 private boolean isActive(ConstructionProject p){return p.state()!=ConstructionProjectState.COMPLETE&&p.state()!=ConstructionProjectState.PAUSED&&p.state()!=ConstructionProjectState.CANCELLED;}
 private Set<UUID> assignedBuilderIds(ConstructionProject p){return new HashSet<>(p.claims().values());}
 public void pickedUp(ConstructionProject p,UUID citizen,ResourceLocation item,int amount){p.cargoPickedUp(citizen,item,amount);data.setDirty();}
 public void consumed(ConstructionProject p,UUID citizen,ResourceLocation item,int amount){p.cargoConsumed(citizen,item,amount);data.setDirty();}
 public void release(UUID project,int index,UUID citizen){data.project(project).ifPresent(p->p.release(index,citizen));data.setDirty();}
 public void failed(UUID project,int index,UUID citizen){data.project(project).ifPresent(p->p.failed(index,citizen));data.setDirty();}
 public void placed(ConstructionProject p,int index,UUID citizen){p.markComplete(index,citizen);attemptComplete(p);data.setDirty();}
 public void onDeath(CitizenRecord citizen,ServerLevel level){for(var p:data.projects()){p.releaseAll(citizen.citizenId());returnTrackedCargo(p,citizen,level);}data.setDirty();}
 public Optional<Container> stockpile(ConstructionProject p,ServerLevel l){if(!p.stockpile().isIn(l)||!l.isLoaded(p.stockpile().pos()))return Optional.empty();return l.getBlockEntity(p.stockpile().pos()) instanceof Container c?Optional.of(c):Optional.empty();}
 public boolean protects(UUID settlementId,ServerLevel level,BlockPos pos){return data.projects().stream().anyMatch(p->p.settlementId().equals(settlementId)&&p.state()!=ConstructionProjectState.CANCELLED&&p.anchor().isIn(level)&&(p.plansWorldPosition(pos)||p.temporaryAccess().stream().anyMatch(a->a.isIn(level)&&a.pos().equals(pos))));}
 public Map<ResourceLocation,MaterialAccounting> accounting(ConstructionProject p){Map<ResourceLocation,Integer> required=requirements(p.blueprint()),remaining=requirementsRemaining(p);Map<ResourceLocation,MaterialAccounting> result=new LinkedHashMap<>();ServerLevel level=server.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,p.stockpile().dimension()));Container stock=level==null?null:stockpile(p,level).orElse(null);for(var e:required.entrySet()){ItemKey key=ItemKey.parse(e.getKey().toString());int placed=e.getValue()-remaining.getOrDefault(e.getKey(),0),stockpiled=stock==null?0:count(stock,key),held=p.held(e.getKey()),missing=Math.max(0,e.getValue()-placed-stockpiled-held);result.put(e.getKey(),new MaterialAccounting(e.getValue(),placed,stockpiled,held,missing));}return result;}
 public AssignedLocation accessTarget(ConstructionProject p,int blockIndex){var r=p.blueprint().blocks().get(blockIndex).relativePos();if(r.y()>=4&&!p.temporaryAccess().isEmpty())return new AssignedLocation(p.anchor().dimension(),p.anchor().pos().offset(r.x()<3?-1:7,5,4));BlockPos target=r.resolve(p.anchor().pos());if(r.y()==0){ServerLevel level=server.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,p.anchor().dimension()));if(level!=null)for(Direction direction:Direction.Plane.HORIZONTAL){BlockPos adjacent=target.relative(direction);if(!p.plansWorldPosition(adjacent)&&level.getBlockState(adjacent.below()).isSolidRender(level,adjacent.below()))return new AssignedLocation(p.anchor().dimension(),adjacent);if(p.plansWorldPosition(adjacent)&&!level.getBlockState(adjacent).isAir())return new AssignedLocation(p.anchor().dimension(),adjacent.above());}}int x=r.x(),z=r.z(),edge=Math.min(Math.min(r.x(),6-r.x()),Math.min(r.z(),8-r.z()));if(edge==r.x())x=-1;else if(edge==6-r.x())x=7;else if(edge==r.z())z=-1;else z=9;return new AssignedLocation(p.anchor().dimension(),p.anchor().pos().offset(x,0,z));}
 private void ensureTemporaryAccess(ConstructionProject p,ServerLevel level){if(!p.temporaryAccess().isEmpty())cleanupTemporaryAccess(p,level);p.clearAccessFailures();p.setState(ConstructionProjectState.READY,ConstructionBlocker.NONE);data.setDirty();}
 private void cleanupTemporaryAccess(ConstructionProject p,ServerLevel level){for(var a:p.temporaryAccess())if(a.isIn(level)&&level.getBlockState(a.pos()).is(Blocks.SCAFFOLDING))level.removeBlock(a.pos(),false);p.clearTemporaryAccess();}
 private void revalidateCompleted(ConstructionProject p,ServerLevel level){for(int i=0;i<p.totalPlacements();i++)if(p.complete(i)){var planned=p.blueprint().blocks().get(i);BlockPos pos=planned.relativePos().resolve(p.anchor().pos());if(!level.getBlockState(pos).is(BuiltInRegistries.BLOCK.get(planned.blockId()))){CivilisationMod.LOGGER.warn("Reopening {} placement {} at {} because the world no longer matches {}",p.readableId(),i,pos.toShortString(),planned.blockId());p.reopen(i);}}}
 private void attemptComplete(ConstructionProject p){if(p.completedPlacements()!=p.totalPlacements()||p.registeredBuildingId().isPresent())return;ServerLevel level=server.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,p.anchor().dimension()));if(level==null||!level.isLoaded(p.anchor().pos()))return;for(var b:p.blueprint().blocks())if(!level.getBlockState(b.relativePos().resolve(p.anchor().pos())).is(BuiltInRegistries.BLOCK.get(b.blockId()))){p.setState(ConstructionProjectState.BLOCKED,ConstructionBlocker.WORLD_CHANGED);return;}for(UUID owner:p.cargoOwners()){CitizenRecord citizen=com.tyes.civilisation.persistence.CitizenSavedData.get(server).registry().find(owner).orElse(null);if(citizen!=null)returnTrackedCargo(p,citizen,level);}if(p.heldTotal()>0){p.setState(ConstructionProjectState.BLOCKED,ConstructionBlocker.CARGO_STRANDED);return;}cleanupTemporaryAccess(p,level);UUID building=UUID.randomUUID();p.registered(building);p.setState(ConstructionProjectState.COMPLETE,ConstructionBlocker.NONE);data.addBuilding(new BuildingRecord(building,p.projectId(),p.settlementId(),p.anchor(),p.blueprint().buildingType(),p.blueprint().style(),p.palette(),2,BuildingCondition.INTACT,List.of(),server.overworld().getGameTime()));CivilisationServices.economy(server).reservations().releaseOwner(p.settlementId(),p.projectId());CivilisationServices.demography(server).reconcileHomes(p.settlementId());}
 private void reconcileCargoReferences(CitizenRecord citizen){for(var p:data.projects())for(var e:p.heldBy(citizen.citizenId()).entrySet()){int actual=citizen.inventory().count(ItemKey.parse(e.getKey().toString()));if(actual<e.getValue())p.cargoConsumed(citizen.citizenId(),e.getKey(),e.getValue()-actual);}}
 private void returnTrackedCargo(ConstructionProject p,CitizenRecord citizen,ServerLevel level){Container destination=stockpile(p,level).orElse(null);for(var e:new ArrayList<>(p.heldBy(citizen.citizenId()).entrySet())){ItemKey key=ItemKey.parse(e.getKey().toString());int moved=destination==null?0:citizen.inventory().transferMatchingTo(destination,key,e.getValue());if(moved<e.getValue()){var alt=CivilisationServices.economy(server).alternateStorage(p.settlementId(),p.stockpileEndpoint()).orElse(null);if(alt!=null){var resolved=alt.resolve(level);if(resolved.isPresent())moved+=citizen.inventory().transferMatchingTo(resolved.get(),key,e.getValue()-moved);}}p.cargoConsumed(citizen.citizenId(),e.getKey(),moved);if(moved<e.getValue())p.setState(ConstructionProjectState.BLOCKED,ConstructionBlocker.CARGO_STRANDED);}}
 private int count(Container c,ItemKey key){return PhysicalInventoryOps.snapshot(c).entrySet().stream().filter(e->e.getKey().itemId().equals(key.itemId())).mapToInt(Map.Entry::getValue).sum();}
 private ArchitectureStyleProfile style(ServerLevel l,BlockPos p){var b=l.getBiome(p);if(b.is(BiomeTags.IS_JUNGLE))return ArchitectureStyles.JUNGLE;if(b.is(BiomeTags.IS_BADLANDS)||b.unwrapKey().map(k->k.location().getPath().contains("desert")).orElse(false))return ArchitectureStyles.DESERT;return ArchitectureStyles.TEMPERATE;}
 private MaterialPalette palette(ArchitectureStyleProfile s,SettlementState settlement,ServerLevel level){
  Map<MaterialRole,ResourceLocation> m=new EnumMap<>(MaterialRole.class);boolean desert=s==ArchitectureStyles.DESERT,jungle=s==ArchitectureStyles.JUNGLE;
  Block preferredWood=jungle?Blocks.JUNGLE_LOG:Blocks.OAK_LOG;Block wood=available(settlement,level,preferredWood)>0?preferredWood:firstAvailable(settlement,level,List.of(Blocks.OAK_LOG,Blocks.JUNGLE_LOG,Blocks.ACACIA_LOG,Blocks.SPRUCE_LOG,Blocks.BIRCH_LOG,Blocks.DARK_OAK_LOG),preferredWood);
  Block planks=planksFor(wood);Block foundation=available(settlement,level,Blocks.COBBLESTONE)>0?Blocks.COBBLESTONE:(desert&&available(settlement,level,Blocks.SANDSTONE)>0?Blocks.SANDSTONE:Blocks.COBBLESTONE);
  Block wall=desert&&available(settlement,level,Blocks.CUT_SANDSTONE)>0?Blocks.CUT_SANDSTONE:planks;Block roof=desert&&available(settlement,level,Blocks.SMOOTH_SANDSTONE)>0?Blocks.SMOOTH_SANDSTONE:wall;
  m.put(MaterialRole.FOUNDATION,key(foundation));m.put(MaterialRole.STRUCTURAL_TIMBER,key(wood));m.put(MaterialRole.WALL_PRIMARY,key(wall));m.put(MaterialRole.FLOOR,key(wall));m.put(MaterialRole.ROOF,key(roof));return new MaterialPalette(m);
 }
 private int available(SettlementState settlement,ServerLevel level,Block block){Item item=block.asItem();int total=0;for(AssignedLocation location:settlement.storageLocations())if(location.isIn(level)&&level.isLoaded(location.pos())&&level.getBlockEntity(location.pos()) instanceof Container container)for(int slot=0;slot<container.getContainerSize();slot++)if(container.getItem(slot).is(item))total+=container.getItem(slot).getCount();return total;}
 private Block firstAvailable(SettlementState settlement,ServerLevel level,List<Block> candidates,Block fallback){return candidates.stream().filter(block->available(settlement,level,block)>0).findFirst().orElse(fallback);}
 private Block planksFor(Block log){if(log==Blocks.JUNGLE_LOG)return Blocks.JUNGLE_PLANKS;if(log==Blocks.ACACIA_LOG)return Blocks.ACACIA_PLANKS;if(log==Blocks.SPRUCE_LOG)return Blocks.SPRUCE_PLANKS;if(log==Blocks.BIRCH_LOG)return Blocks.BIRCH_PLANKS;if(log==Blocks.DARK_OAK_LOG)return Blocks.DARK_OAK_PLANKS;return Blocks.OAK_PLANKS;}
 private ResolvedBlueprint starter(ArchitectureStyleProfile s,MaterialPalette p){List<PlannedBlock>b=new ArrayList<>();for(int x=0;x<7;x++)for(int z=0;z<9;z++)b.add(pb(x,0,z,p.require(MaterialRole.FOUNDATION),true));for(int x=0;x<7;x++)for(int z=0;z<9;z++)if((x==0||x==6||z==0||z==8)&&!(z==0&&x==3))b.add(pb(x,1,z,p.require((x==0||x==6)&&(z==0||z==8)?MaterialRole.STRUCTURAL_TIMBER:MaterialRole.WALL_PRIMARY),true));for(int y=2;y<=3;y++)for(int x:new int[]{0,6})for(int z:new int[]{0,8})b.add(pb(x,y,z,p.require(MaterialRole.STRUCTURAL_TIMBER),true));for(int y=2;y<=3;y++)for(int x=0;x<7;x++)for(int z=0;z<9;z++)if((x==0||x==6||z==0||z==8)&&!((x==0||x==6)&&(z==0||z==8))&&!(z==0&&x==3&&y==2))b.add(pb(x,y,z,p.require(MaterialRole.WALL_PRIMARY),true));for(int x=0;x<7;x++)for(int z=0;z<9;z++)b.add(pb(x,4,z,p.require(MaterialRole.ROOF),true));return new ResolvedBlueprint(UUID.randomUUID(),ResourceLocation.fromNamespaceAndPath(CivilisationMod.MOD_ID,"starter_house"),s.id(),1,b);}
 private PlannedBlock pb(int x,int y,int z,ResourceLocation id,boolean structural){return new PlannedBlock(new RelativeBlockPos(x,y,z),id,structural);}private ResourceLocation key(Block b){return BuiltInRegistries.BLOCK.getKey(b);}private Map<ResourceLocation,Integer> requirements(ResolvedBlueprint b){Map<ResourceLocation,Integer>m=new LinkedHashMap<>();b.blocks().forEach(x->m.merge(x.blockId(),1,Integer::sum));return m;}
 private Map<ResourceLocation,Integer> requirementsRemaining(ConstructionProject p){Map<ResourceLocation,Integer>m=new LinkedHashMap<>();for(int i=0;i<p.totalPlacements();i++)if(!p.complete(i))m.merge(p.blueprint().blocks().get(i).blockId(),1,Integer::sum);return m;}
 private void validateSite(ServerLevel l,BlockPos a,ResolvedBlueprint b){for(var x:b.blocks()){BlockPos p=x.relativePos().resolve(a);if(!l.isLoaded(p))throw new IllegalStateException("Site chunk unloaded");var state=l.getBlockState(p);if(!state.isAir()&&!state.canBeReplaced())throw new IllegalStateException("Site obstructed at "+p.toShortString());}}
 private record Site(BlockPos anchor,BlockPos stockpile,ArchitectureStyleProfile style){}
 public record Claim(UUID projectId,int blockIndex,ConstructionPriority priority){}
 public record MaterialAccounting(int required,int placed,int stockpiled,int builderHeld,int missing){}
}
